MODULE CMF_CTRL_MAPS_MOD
!==========================================================
!* PURPOSE: Control CaMa-Flood map/topography data
!
!* CONTAINS:
! -- CMF_MAPS_NMLIST   : configuration from namelist
! -- CMF_RIVMAP_INIT  : read & set river network map 
! -- CMF_TOPO_INIT    : read & set topography
!
! (C) D.Yamazaki & E. Dutra  (U-Tokyo/FCUL)  Aug 2019
!
! Licensed under the Apache License, Version 2.0 (the "License");
!   You may not use this file except in compliance with the License.
!   You may obtain a copy of the License at: http://www.apache.org/licenses/LICENSE-2.0
!
! Unless required by applicable law or agreed to in writing, software distributed under the License is 
!  distributed on an "AS IS" BASIS, WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied. 
! See the License for the specific language governing permissions and limitations under the License.
!==========================================================
! shared variables in module
USE PARKIND1,                ONLY: JPIM, JPRB, JPRD, JPRM
USE YOS_CMF_INPUT,           ONLY: LOGNAM, CROUTINGNC
IMPLICIT NONE
SAVE
!*** NAMELIST/NMAP/ from inputnam
CHARACTER(LEN=256)              :: CNEXTXY         !! river network nextxy
CHARACTER(LEN=256)              :: CGRAREA         !! catchment area
CHARACTER(LEN=256)              :: CELEVTN         !! bank top elevation
CHARACTER(LEN=256)              :: CNXTDST         !! distance to next outlet
CHARACTER(LEN=256)              :: CRIVLEN         !! river channel length
CHARACTER(LEN=256)              :: CFLDHGT         !! floodplain elevation profile
CHARACTER(LEN=256)              :: CGRDARE         !! grid area
!* river channel parameters
CHARACTER(LEN=256)              :: CRIVWTH         !! channel width
CHARACTER(LEN=256)              :: CRIVHGT         !! channel depth
CHARACTER(LEN=256)              :: CRIVMAN         !! river manning coefficient
!* optional maps
CHARACTER(LEN=256)              :: CPTHOUT         !! bifurcation channel table
CHARACTER(LEN=256)              :: CGDWDLY         !! Groundwater Delay Parameter
CHARACTER(LEN=256)              :: CMEANSL         !! mean sea level
!* MPI parallelization
CHARACTER(LEN=256)              :: CMPIREG         !! MPI region map
!* netCDF map
LOGICAL                         :: LMAPCDF         !! true for netCDF map input
CHARACTER(LEN=256)              :: CRIVCLINC       !! river map netcdf
CHARACTER(LEN=256)              :: CRIVPARNC       !! river parameter netcdf (WIDTH,HEIGHT, Manning, ground wateer delay)
CHARACTER(LEN=256)              :: CMEANSLNC       !! mean sea level netCDF
CHARACTER(LEN=256)              :: CMPIREGNC       !! MPI region map in netcdf

NAMELIST/NMAP/     CNEXTXY,  CGRAREA,  CELEVTN,  CNXTDST, CRIVLEN, CFLDHGT, CGRDARE, &
                   CRIVWTH,  CRIVHGT,  CRIVMAN,  CPTHOUT, CGDWDLY, CMEANSL, &
                   CMPIREG,  LMAPCDF,  CRIVCLINC,CRIVPARNC,CMEANSLNC,CMPIREGNC,CROUTINGNC


CONTAINS
!####################################################################
! -- CMF_MAP_NMLIST   : configuration from namelist
! -- CMF_RIVMAP_INIT  : read & set river network map 
! -- CMF_TOPO_INIT    : read & set topography
!
!
!####################################################################
SUBROUTINE CMF_MAPS_NMLIST(ROUTING_FILE)
! reed setting from namelist
! -- Called from CMF_DRV_NMLIST
USE YOS_CMF_INPUT,      ONLY: CSETFILE,NSETFILE,LMEANSL,LGDWDLY
USE CMF_UTILS_MOD,      ONLY: INQUIRE_FID
IMPLICIT NONE
CHARACTER(LEN=*),OPTIONAL,INTENT(IN) :: ROUTING_FILE
LOGICAL :: FILE_EXISTS
!================================================
!*** 1. open namelist
WRITE(LOGNAM,*) ""
WRITE(LOGNAM,*) "!---------------------!"

NSETFILE=INQUIRE_FID()
IF( CSETFILE/="NONE" ) OPEN(NSETFILE,FILE=CSETFILE,STATUS="OLD")
IF( CSETFILE/="NONE" ) WRITE(LOGNAM,*) "CMF::MAP_NMLIST: namelist OPEN in unit: ", TRIM(CSETFILE), NSETFILE

!*** 2. default value
CNEXTXY="./nextxy.bin"
CGRAREA="./ctmare.bin"
CELEVTN="./elevtn.bin"
CNXTDST="./nxtdst.bin"
CRIVLEN="./rivlen.bin"
CFLDHGT="./fldhgt.bin"
CGRDARE="./grdare.bin"

CRIVWTH="./rivwth.bin"
CRIVHGT="./rivhgt.bin"
CRIVMAN="./rivman.bin"

CPTHOUT="./bifprm.txt"
CGDWDLY="NONE"
CMEANSL="NONE"

CMPIREG="NONE"
CROUTINGNC="NONE"

LMAPCDF=.FALSE.
CRIVCLINC="NONE"
CRIVPARNC="NONE"
CMEANSLNC="NONE"
CMPIREGNC="NONE"

!*** 3. read namelist
IF( CSETFILE/="NONE" ) REWIND(NSETFILE)
IF( CSETFILE/="NONE" ) READ(NSETFILE,NML=NMAP)
IF( PRESENT(ROUTING_FILE) )THEN
  SELECT CASE(TRIM(ROUTING_FILE))
  CASE('', 'null', 'NULL', 'none', 'NONE')
  CASE DEFAULT
    IF( LEN_TRIM(ROUTING_FILE)>LEN(CROUTINGNC) ) ERROR STOP 'CaMa routing path too long'
    CROUTINGNC=TRIM(ROUTING_FILE)
  END SELECT
ENDIF
IF( CROUTINGNC=='' .OR. CROUTINGNC=='none' .OR. CROUTINGNC=='null' .OR. CROUTINGNC=='NULL' ) &
  CROUTINGNC='NONE'
IF( CROUTINGNC/="NONE" )THEN
#ifdef UseMPI_CMF
  ERROR STOP 'CaMa routing NC does not support UseMPI_CMF decomposition'
#endif
  INQUIRE(FILE=TRIM(CROUTINGNC),EXIST=FILE_EXISTS)
  IF( .NOT.FILE_EXISTS ) ERROR STOP 'CaMa routing NC file missing'
  CALL READ_ROUTING_HEADER_CDF
ENDIF

WRITE(LOGNAM,*)     "=== NAMELIST, NMAP ==="
WRITE(LOGNAM,*)     "CROUTINGNC: ", TRIM(CROUTINGNC)
IF( CROUTINGNC/="NONE" )THEN
  WRITE(LOGNAM,*) "Routing topology and parameters from NC"
ELSEIF( LMAPCDF )THEN
  WRITE(LOGNAM,*)   "CRIVCLINC: ", TRIM(CRIVCLINC)
  WRITE(LOGNAM,*)   "CRIVPARNC: ", TRIM(CRIVPARNC)
  IF( LMEANSL ) THEN
    WRITE(LOGNAM,*) "CMEANSLNC: ", TRIM(CMEANSLNC)
  ENDIF
#ifdef UseMPI_CMF
    WRITE(LOGNAM,*) "CMPIREGNC:   ", TRIM(CMPIREGNC)
#endif
ELSE
  WRITE(LOGNAM,*)   "CNEXTXY:   ", TRIM(CNEXTXY)
  WRITE(LOGNAM,*)   "CGRAREA:   ", TRIM(CGRAREA)
  WRITE(LOGNAM,*)   "CELEVTN:   ", TRIM(CELEVTN)
  WRITE(LOGNAM,*)   "CNXTDST:   ", TRIM(CNXTDST)
  WRITE(LOGNAM,*)   "CRIVLEN:   ", TRIM(CRIVLEN)
  WRITE(LOGNAM,*)   "CFLDHGT:   ", TRIM(CFLDHGT)
  WRITE(LOGNAM,*)   "CGRDARE:   ", TRIM(CGRDARE)

  WRITE(LOGNAM,*)   "CRIVWTH:   ", TRIM(CRIVWTH)
  WRITE(LOGNAM,*)   "CRIVHGT:   ", TRIM(CRIVHGT)
  WRITE(LOGNAM,*)   "CRIVMAN:   ", TRIM(CRIVMAN)

  WRITE(LOGNAM,*)   "CPTHOUT:   ", TRIM(CPTHOUT)
  IF( LGDWDLY )THEN
    WRITE(LOGNAM,*) "CGDWDLY:    ",TRIM(CGDWDLY)
  ENDIF
  IF( LMEANSL )THEN
    WRITE(LOGNAM,*) "CMEANSL:   ", TRIM(CMEANSL)
  ENDIF
#ifdef UseMPI_CMF
    WRITE(LOGNAM,*) "CMPIREG:   ", TRIM(CMPIREG)
#endif
ENDIF

IF( CSETFILE/="NONE" ) CLOSE(NSETFILE)

WRITE(LOGNAM,*) "CMF::MAP_NMLIST: end"

END SUBROUTINE CMF_MAPS_NMLIST
!####################################################################





SUBROUTINE READ_ROUTING_HEADER_CDF
USE, INTRINSIC :: IEEE_ARITHMETIC, ONLY: IEEE_IS_FINITE
USE YOS_CMF_INPUT, ONLY: NX,NY,NLFP,NXIN,NYIN,INPN,WEST,EAST,NORTH,SOUTH
#ifdef UseCDF_CMF
USE CMF_UTILS_MOD, ONLY: NCERROR
USE NETCDF
#endif
IMPLICIT NONE
#ifdef UseCDF_CMF
INTEGER(KIND=JPIM) :: NCID,DIMID,VARID,STATUS
INTEGER(KIND=JPIM) :: DIMIDS2(2),NSEQTMP,LEN1,LEN2,SEQDIM

CALL NCERROR(NF90_OPEN(TRIM(CROUTINGNC),NF90_NOWRITE,NCID),'opening '//TRIM(CROUTINGNC))
STATUS=NF90_INQ_DIMID(NCID,'nx',DIMID)
IF( STATUS==NF90_NOERR )THEN
  CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMID,LEN=NX),'reading nx dimension')
ELSE
  CALL NCERROR(NF90_INQ_VARID(NCID,'lon',VARID),'getting lon id')
  CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=DIMIDS2(1:1)),'reading lon dimensions')
  CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS2(1),LEN=NX),'reading lon length')
ENDIF
STATUS=NF90_INQ_DIMID(NCID,'ny',DIMID)
IF( STATUS==NF90_NOERR )THEN
  CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMID,LEN=NY),'reading ny dimension')
ELSE
  CALL NCERROR(NF90_INQ_VARID(NCID,'lat',VARID),'getting lat id')
  CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=DIMIDS2(1:1)),'reading lat dimensions')
  CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS2(1),LEN=NY),'reading lat length')
ENDIF
CALL NCERROR(NF90_INQ_VARID(NCID,'seq_x',VARID),'getting seq_x id')
CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=DIMIDS2(1:1)),'reading seq_x dimensions')
CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS2(1),LEN=NSEQTMP),'reading seq_x length')
SEQDIM=DIMIDS2(1)
STATUS=NF90_INQ_DIMID(NCID,'nlfp',DIMID)
IF( STATUS==NF90_NOERR )THEN
  CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMID,LEN=NLFP),'reading nlfp dimension')
ELSE
  CALL NCERROR(NF90_INQ_VARID(NCID,'topo_fldhgt',VARID),'getting topo_fldhgt id')
  CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=DIMIDS2),'reading topo_fldhgt dimensions')
  CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS2(1),LEN=LEN1),'reading topo_fldhgt dimension')
  CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS2(2),LEN=LEN2),'reading topo_fldhgt dimension')
  IF( DIMIDS2(1)==SEQDIM .AND. LEN1==NSEQTMP )THEN
    NLFP=LEN2
  ELSEIF( DIMIDS2(2)==SEQDIM .AND. LEN2==NSEQTMP )THEN
    NLFP=LEN1
  ELSE
    ERROR STOP 'CaMa invalid floodplain-height dimensions'
  ENDIF
ENDIF
STATUS=NF90_INQ_DIMID(NCID,'inpn',DIMID)
IF( STATUS==NF90_NOERR )THEN
  CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMID,LEN=INPN),'reading inpn dimension')
ELSE
  CALL NCERROR(NF90_INQ_VARID(NCID,'inpmat_area',VARID),'getting inpmat_area id')
  CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=DIMIDS2),'reading inpmat_area dimensions')
  CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS2(1),LEN=LEN1),'reading inpmat_area dimension')
  CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS2(2),LEN=LEN2),'reading inpmat_area dimension')
  IF( DIMIDS2(1)==SEQDIM .AND. LEN1==NSEQTMP )THEN
    INPN=LEN2
  ELSEIF( DIMIDS2(2)==SEQDIM .AND. LEN2==NSEQTMP )THEN
    INPN=LEN1
  ELSE
    ERROR STOP 'CaMa invalid input-matrix dimensions'
  ENDIF
ENDIF
CALL NCERROR(NF90_GET_ATT(NCID,NF90_GLOBAL,'west',WEST),'reading west bound')
CALL NCERROR(NF90_GET_ATT(NCID,NF90_GLOBAL,'east',EAST),'reading east bound')
CALL NCERROR(NF90_GET_ATT(NCID,NF90_GLOBAL,'north',NORTH),'reading north bound')
CALL NCERROR(NF90_GET_ATT(NCID,NF90_GLOBAL,'south',SOUTH),'reading south bound')
CALL NCERROR(NF90_CLOSE(NCID))

IF( NX<=0 .OR. NY<=0 .OR. NLFP<=0 .OR. INPN<=0 ) ERROR STOP 'CaMa invalid routing dimensions'
IF( .NOT.(IEEE_IS_FINITE(WEST) .AND. IEEE_IS_FINITE(EAST) .AND. &
          IEEE_IS_FINITE(NORTH) .AND. IEEE_IS_FINITE(SOUTH)) .OR. &
    EAST<=WEST .OR. NORTH<=SOUTH ) ERROR STOP 'CaMa invalid routing bounds'
NXIN=NX
NYIN=NY
#else
ERROR STOP 'CaMa routing NC requires UseCDF_CMF'
#endif
END SUBROUTINE READ_ROUTING_HEADER_CDF





!####################################################################
SUBROUTINE CMF_RIVMAP_INIT
! read & set river network map 
! -- call from CMF_DRV_INIT
USE YOS_CMF_INPUT,      ONLY: TMPNAM, NX,NY,NLFP, LPTHOUT
USE YOS_CMF_MAP,        ONLY: I2NEXTX,I2NEXTY, I2REGION, REGIONALL,REGIONTHIS, &
                            & I1SEQX, I1SEQY,  I1NEXT,  I2VECTOR, D1LON,    D1LAT,      &
                            & NSEQRIV,NSEQALL, NSEQMAX, NPTHOUT,  NPTHLEV, ROUTING_OLD_TO_NEW
USE YOS_CMF_MAP,        ONLY: I1UPST, I1UPN, I1P_OUT, I1P_OUTN, I1P_INF, I1P_INFN
USE CMF_UTILS_MOD,      ONLY: INQUIRE_FID
IMPLICIT NONE
!================================================
WRITE(LOGNAM,*) ""
WRITE(LOGNAM,*) "!---------------------!"
WRITE(LOGNAM,*) 'CMF::RIVMAP_INIT: river network initialization'

! *** 1. ALLOCATE ARRAYS
ALLOCATE( I2NEXTX(NX,NY) )
ALLOCATE( I2NEXTY(NX,NY) )
ALLOCATE( I2REGION(NX,NY) )
ALLOCATE( D1LON(NX) )
ALLOCATE( D1LAT(NY) )

!============================
!*** 2a. read river network map
WRITE(LOGNAM,*) 'CMF::RIVMAP_INIT: read nextXY & set lat lon'
IF( CROUTINGNC/="NONE" )THEN
#ifdef UseCDF_CMF
  CALL READ_ROUTING_MAP_CDF
#endif
ELSEIF( LMAPCDF )THEN
#ifdef UseCDF_CMF
  CALL READ_MAP_CDF
#endif
ELSE
  CALL READ_MAP_BIN
ENDIF

!*** 2b. calculate river sequence & regions
!============================
!*** 3. conversion 2D map -> 1D vector
IF( CROUTINGNC=="NONE" )THEN
  WRITE(LOGNAM,*) 'CMF::RIVMAP_INIT: calc region'
  CALL CALC_REGION
  WRITE(LOGNAM,*) 'CMF::RIVMAP_INIT: calculate 1d river sequence'
  CALL CALC_1D_SEQ
ENDIF

WRITE(LOGNAM,*) '  NSEQRIV=',NSEQRIV
WRITE(LOGNAM,*) '  NSEQALL=',NSEQALL
WRITE(LOGNAM,*) '  NSEQMAX=',NSEQMAX

!*** 3c. Write Map Data                                       !! used for combining mpi distributed output into one map
IF( REGIONTHIS==1 )THEN
  TMPNAM=INQUIRE_FID()
  OPEN(TMPNAM,FILE='./mapdata.txt',FORM='FORMATTED')
  WRITE(TMPNAM,*) 'NX',        NX
  WRITE(TMPNAM,*) 'NY',        NY
  WRITE(TMPNAM,*) 'NLFP',      NLFP
  WRITE(TMPNAM,*) 'REGIONALL', REGIONALL
  WRITE(TMPNAM,*) 'NSEQMAX',   NSEQMAX
  CLOSE(TMPNAM)
ENDIF

!============================
!*** 4.  bifurcation channel parameters
NPTHOUT=1  !! tentative number
NPTHLEV=1
IF( LPTHOUT )THEN
  WRITE(LOGNAM,*) 'CMF::RIVMAP_INIT: read bifurcation channel setting'
  IF( CROUTINGNC/="NONE" )THEN
#ifdef UseCDF_CMF
    CALL READ_ROUTING_BIF_CDF
#endif
  ELSE
    CALL READ_BIFPARAM
  ENDIF
ENDIF

!DEALLOCATE( I2NEXTX,I2NEXTY,I2REGION )
DEALLOCATE( I2NEXTY,I2REGION )

WRITE(LOGNAM,*) 'CMF::RIVMAP_INIT: end'

CONTAINS
!==========================================================
!+ READ_MAP_BIN
!+ READ_MAP_CDF
!+ CALC_REGION
!+ CALC_1D_SEQ
!+ READ_BIFPRM
!==========================================================
#ifdef UseCDF_CMF
SUBROUTINE READ_ROUTING_MAP_CDF
USE YOS_CMF_INPUT, ONLY: IMIS
USE CMF_UTILS_MOD, ONLY: NCERROR
USE NETCDF
IMPLICIT NONE
INTEGER(KIND=JPIM) :: NCID,VARID,ISEQ,JSEQ,IX,IY,QHEAD,QTAIL,NVISIT,UPNMAX
INTEGER(KIND=JPIM) :: DIMIDS1(1)
INTEGER(KIND=JPIM),ALLOCATABLE :: SEQX_RAW(:),SEQY_RAW(:),NEXT_RAW(:),NUPCALC(:),NUPWORK(:),QUEUE(:),ORDER(:)

CALL NCERROR(NF90_OPEN(TRIM(CROUTINGNC),NF90_NOWRITE,NCID),'opening '//TRIM(CROUTINGNC))
CALL NCERROR(NF90_INQ_VARID(NCID,'seq_x',VARID),'getting seq_x id')
CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=DIMIDS1),'reading seq_x dimensions')
CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS1(1),LEN=NSEQMAX),'reading seq_x length')
IF( NSEQMAX<=0 ) ERROR STOP 'CaMa invalid routing sequence dimension'

ALLOCATE(I1SEQX(NSEQMAX),I1SEQY(NSEQMAX),I1NEXT(NSEQMAX),I2VECTOR(NX,NY))
ALLOCATE(SEQX_RAW(NSEQMAX),SEQY_RAW(NSEQMAX),NEXT_RAW(NSEQMAX))
ALLOCATE(NUPCALC(NSEQMAX),NUPWORK(NSEQMAX),QUEUE(NSEQMAX),ORDER(NSEQMAX))
NUPCALC=0
CALL NCERROR(NF90_INQ_VARID(NCID,'lon',VARID),'getting lon id')
CALL NCERROR(NF90_GET_VAR(NCID,VARID,D1LON),'reading lon')
CALL NCERROR(NF90_INQ_VARID(NCID,'lat',VARID),'getting lat id')
CALL NCERROR(NF90_GET_VAR(NCID,VARID,D1LAT),'reading lat')
CALL NCERROR(NF90_INQ_VARID(NCID,'seq_x',VARID),'getting seq_x id')
CALL NCERROR(NF90_GET_VAR(NCID,VARID,SEQX_RAW),'reading seq_x')
CALL NCERROR(NF90_INQ_VARID(NCID,'seq_y',VARID),'getting seq_y id')
CALL NCERROR(NF90_GET_VAR(NCID,VARID,SEQY_RAW),'reading seq_y')
CALL NCERROR(NF90_INQ_VARID(NCID,'seq_next',VARID),'getting seq_next id')
CALL NCERROR(NF90_GET_VAR(NCID,VARID,NEXT_RAW),'reading seq_next')
CALL NCERROR(NF90_CLOSE(NCID))

I1SEQX=SEQX_RAW
I1SEQY=SEQY_RAW
I1NEXT=NEXT_RAW
I2NEXTX=IMIS
I2NEXTY=IMIS
I2REGION=IMIS
I2VECTOR=0
REGIONALL=1
NSEQALL=NSEQMAX
DO ISEQ=1,NSEQMAX
  IX=I1SEQX(ISEQ)
  IY=I1SEQY(ISEQ)
  IF( IX<1 .OR. IX>NX .OR. IY<1 .OR. IY>NY ) ERROR STOP 'CaMa routing grid index out of range'
  IF( I2VECTOR(IX,IY)/=0 ) ERROR STOP 'CaMa duplicate routing grid index'
  I2VECTOR(IX,IY)=ISEQ
  I2REGION(IX,IY)=1
ENDDO
DO ISEQ=1,NSEQMAX
  JSEQ=I1NEXT(ISEQ)
  IF( JSEQ>0 )THEN
    IF( JSEQ>NSEQMAX .OR. JSEQ==ISEQ ) ERROR STOP 'CaMa invalid downstream sequence'
    NUPCALC(JSEQ)=NUPCALC(JSEQ)+1
  ENDIF
ENDDO

NSEQRIV=COUNT(I1NEXT>0)
QHEAD=1
QTAIL=0
DO ISEQ=1,NSEQMAX
  IF( NUPCALC(ISEQ)==0 .AND. I1NEXT(ISEQ)>0 )THEN
    QTAIL=QTAIL+1
    QUEUE(QTAIL)=ISEQ
  ENDIF
ENDDO
NVISIT=0
NUPWORK=NUPCALC
DO WHILE( QHEAD<=QTAIL )
  ISEQ=QUEUE(QHEAD)
  QHEAD=QHEAD+1
  NVISIT=NVISIT+1
  ORDER(NVISIT)=ISEQ
  JSEQ=I1NEXT(ISEQ)
  IF( JSEQ>0 )THEN
    NUPWORK(JSEQ)=NUPWORK(JSEQ)-1
    IF( NUPWORK(JSEQ)==0 .AND. I1NEXT(JSEQ)>0 )THEN
      QTAIL=QTAIL+1
      QUEUE(QTAIL)=JSEQ
    ENDIF
  ENDIF
ENDDO
IF( NVISIT/=NSEQRIV ) ERROR STOP 'CaMa routing sequence contains a cycle'
DO ISEQ=1,NSEQMAX
  IF( I1NEXT(ISEQ)<=0 )THEN
    NVISIT=NVISIT+1
    ORDER(NVISIT)=ISEQ
  ENDIF
ENDDO
IF( ALLOCATED(ROUTING_OLD_TO_NEW) ) DEALLOCATE(ROUTING_OLD_TO_NEW)
ALLOCATE(ROUTING_OLD_TO_NEW(NSEQMAX))
DO ISEQ=1,NSEQMAX
  ROUTING_OLD_TO_NEW(ORDER(ISEQ))=ISEQ
ENDDO
DO ISEQ=1,NSEQMAX
  JSEQ=ORDER(ISEQ)
  I1SEQX(ISEQ)=SEQX_RAW(JSEQ)
  I1SEQY(ISEQ)=SEQY_RAW(JSEQ)
  IF( NEXT_RAW(JSEQ)>0 )THEN
    I1NEXT(ISEQ)=ROUTING_OLD_TO_NEW(NEXT_RAW(JSEQ))
  ELSE
    I1NEXT(ISEQ)=NEXT_RAW(JSEQ)
  ENDIF
ENDDO
NUPCALC=0
DO ISEQ=1,NSEQRIV
  JSEQ=I1NEXT(ISEQ)
  NUPCALC(JSEQ)=NUPCALC(JSEQ)+1
ENDDO
UPNMAX=MAX(1,MAXVAL(NUPCALC))
ALLOCATE(I1UPST(NSEQMAX,UPNMAX),I1UPN(NSEQMAX))
I1UPST=-9999
I1UPN=NUPCALC
NUPCALC=0
DO ISEQ=1,NSEQRIV
  JSEQ=I1NEXT(ISEQ)
  NUPCALC(JSEQ)=NUPCALC(JSEQ)+1
  I1UPST(JSEQ,NUPCALC(JSEQ))=ISEQ
ENDDO
DO ISEQ=1,NSEQMAX
  IX=I1SEQX(ISEQ)
  IY=I1SEQY(ISEQ)
  I2VECTOR(IX,IY)=ISEQ
  JSEQ=I1NEXT(ISEQ)
  IF( JSEQ>0 )THEN
    I2NEXTX(IX,IY)=I1SEQX(JSEQ)
    I2NEXTY(IX,IY)=I1SEQY(JSEQ)
  ELSE
    I2NEXTX(IX,IY)=JSEQ
    I2NEXTY(IX,IY)=JSEQ
  ENDIF
ENDDO
DEALLOCATE(SEQX_RAW,SEQY_RAW,NEXT_RAW,NUPCALC,NUPWORK,QUEUE,ORDER)
END SUBROUTINE READ_ROUTING_MAP_CDF
#endif
SUBROUTINE READ_MAP_BIN
USE YOS_CMF_INPUT,      ONLY: TMPNAM, LMAPEND
USE YOS_CMF_INPUT,      ONLY: WEST,EAST,NORTH,SOUTH
USE CMF_UTILS_MOD,      ONLY: INQUIRE_FID, CONV_ENDI
IMPLICIT NONE
!* local variables
INTEGER(KIND=JPIM),SAVE    :: IX,IY
!==========================================================
!*** read river map
WRITE(LOGNAM,*)'RIVMAP_INIT: nextxy binary: ',TRIM(CNEXTXY)
TMPNAM=INQUIRE_FID()
OPEN(TMPNAM,FILE=CNEXTXY,FORM='UNFORMATTED',ACCESS='DIRECT',RECL=4*NX*NY)
READ(TMPNAM,REC=1) I2NEXTX
READ(TMPNAM,REC=2) I2NEXTY
CLOSE(TMPNAM)

IF ( LMAPEND )THEN
  CALL CONV_ENDI(I2NEXTX,NX,NY)
  CALL CONV_ENDI(I2NEXTY,NX,NY)
ENDIF

!*** calculate lat, lon
IF( WEST>=-180._JPRB .and. EAST<=360._JPRB .and. SOUTH>=-180._JPRB .and. NORTH<=180._JPRB )THEN  !! bugfix_v396a
  !$OMP PARALLEL DO
  DO IX=1,NX
    D1LON(IX)=WEST +(REAL(IX,KIND=JPRB)-0.5_JPRB)*(EAST-WEST)  /REAL(NX,KIND=JPRB)
  ENDDO
  !$OMP END PARALLEL DO
  !$OMP PARALLEL DO
  DO IY=1,NY
    D1LAT(IY)=NORTH-(REAL(IY,KIND=JPRB)-0.5_JPRB)*(NORTH-SOUTH)/REAL(NY,KIND=JPRB)
  ENDDO
  !$OMP END PARALLEL DO
ENDIF

END SUBROUTINE READ_MAP_BIN
!==========================================================
!+
!+
