#ifdef UseCDF_CMF
SUBROUTINE READ_ROUTING_BIF_CDF
USE, INTRINSIC :: IEEE_ARITHMETIC, ONLY: IEEE_IS_FINITE
USE YOS_CMF_MAP, ONLY: PTH_UPST,PTH_DOWN,PTH_DST,PTH_ELV,PTH_WTH,PTH_MAN, ROUTING_OLD_TO_NEW
USE CMF_UTILS_MOD, ONLY: NCERROR
USE NETCDF
IMPLICIT NONE
INTEGER(KIND=JPIM) :: NCID,VARID,DIMID,STATUS,DIMIDS1(1),DIMIDS2(2)
INTEGER(KIND=JPIM) :: IPTH,ILEV,ISEQ,JSEQ,ONMAX,INMAX,LEN1,LEN2,PATH_DIMID,LEV_DIMID
INTEGER(KIND=JPIM),ALLOCATABLE :: OCOUNT(:),ICOUNT(:)
REAL(KIND=JPRB),ALLOCATABLE :: RTEMP(:,:)

CALL NCERROR(NF90_OPEN(TRIM(CROUTINGNC),NF90_NOWRITE,NCID), &
             'opening '//TRIM(CROUTINGNC))
STATUS=NF90_INQ_DIMID(NCID,'npthout',DIMID)
IF( STATUS==NF90_NOERR )THEN
  CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMID,LEN=NPTHOUT),'reading npthout dimension')
ELSE
  CALL NCERROR(NF90_INQ_VARID(NCID,'bifurcation_upst',VARID),'getting bifurcation_upst id')
  CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=DIMIDS1),'reading bifurcation_upst dimensions')
  CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS1(1),LEN=NPTHOUT),'reading bifurcation count')
ENDIF
STATUS=NF90_INQ_DIMID(NCID,'npthlev',DIMID)
IF( STATUS==NF90_NOERR )THEN
  CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMID,LEN=NPTHLEV),'reading npthlev dimension')
ELSE
  CALL NCERROR(NF90_INQ_VARID(NCID,'bifurcation_manning',VARID),'getting bifurcation_manning id')
  CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=DIMIDS1),'reading bifurcation_manning dimensions')
  CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS1(1),LEN=NPTHLEV),'reading bifurcation level count')
ENDIF
IF( NPTHOUT<=0 .OR. NPTHLEV<=0 )THEN
  WRITE(LOGNAM,*) 'Invalid bifurcation dimensions: ',NPTHOUT,NPTHLEV
  STOP 10
ENDIF

ALLOCATE(PTH_UPST(NPTHOUT),PTH_DOWN(NPTHOUT),PTH_DST(NPTHOUT))
ALLOCATE(PTH_ELV(NPTHOUT,NPTHLEV),PTH_WTH(NPTHOUT,NPTHLEV),PTH_MAN(NPTHLEV))

CALL NCERROR(NF90_INQ_VARID(NCID,'bifurcation_upst',VARID),'getting bifurcation_upst id')
CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=DIMIDS1),'reading bifurcation_upst dimensions')
PATH_DIMID=DIMIDS1(1)
CALL NCERROR(NF90_GET_VAR(NCID,VARID,PTH_UPST),'reading bifurcation_upst')
CALL NCERROR(NF90_INQ_VARID(NCID,'bifurcation_down',VARID),'getting bifurcation_down id')
CALL NCERROR(NF90_GET_VAR(NCID,VARID,PTH_DOWN),'reading bifurcation_down')
CALL NCERROR(NF90_INQ_VARID(NCID,'bifurcation_distance',VARID),'getting bifurcation_distance id')
CALL NCERROR(NF90_GET_VAR(NCID,VARID,PTH_DST),'reading bifurcation_distance')
CALL NCERROR(NF90_INQ_VARID(NCID,'bifurcation_manning',VARID),'getting bifurcation_manning id')
CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=DIMIDS1),'reading bifurcation_manning dimensions')
LEV_DIMID=DIMIDS1(1)

CALL NCERROR(NF90_INQ_VARID(NCID,'bifurcation_elevation',VARID),'getting bifurcation_elevation id')
CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=DIMIDS2),'reading bifurcation_elevation dimensions')
CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS2(1),LEN=LEN1),'reading bifurcation_elevation dimension')
CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS2(2),LEN=LEN2),'reading bifurcation_elevation dimension')
IF( DIMIDS2(1)==PATH_DIMID .AND. DIMIDS2(2)==LEV_DIMID )THEN
  ALLOCATE(RTEMP(NPTHOUT,NPTHLEV))
  CALL NCERROR(NF90_GET_VAR(NCID,VARID,RTEMP),'reading bifurcation_elevation')
  PTH_ELV=RTEMP
ELSEIF( DIMIDS2(1)==LEV_DIMID .AND. DIMIDS2(2)==PATH_DIMID )THEN
  ALLOCATE(RTEMP(NPTHLEV,NPTHOUT))
  CALL NCERROR(NF90_GET_VAR(NCID,VARID,RTEMP),'reading bifurcation_elevation')
  PTH_ELV=TRANSPOSE(RTEMP)
ELSE
  WRITE(LOGNAM,*) 'Invalid bifurcation_elevation dimensions: ',LEN1,LEN2,NPTHOUT,NPTHLEV
  STOP 10
ENDIF
DEALLOCATE(RTEMP)

CALL NCERROR(NF90_INQ_VARID(NCID,'bifurcation_width',VARID),'getting bifurcation_width id')
CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=DIMIDS2),'reading bifurcation_width dimensions')
CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS2(1),LEN=LEN1),'reading bifurcation_width dimension')
CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS2(2),LEN=LEN2),'reading bifurcation_width dimension')
IF( DIMIDS2(1)==PATH_DIMID .AND. DIMIDS2(2)==LEV_DIMID )THEN
  ALLOCATE(RTEMP(NPTHOUT,NPTHLEV))
  CALL NCERROR(NF90_GET_VAR(NCID,VARID,RTEMP),'reading bifurcation_width')
  PTH_WTH=RTEMP
ELSEIF( DIMIDS2(1)==LEV_DIMID .AND. DIMIDS2(2)==PATH_DIMID )THEN
  ALLOCATE(RTEMP(NPTHLEV,NPTHOUT))
  CALL NCERROR(NF90_GET_VAR(NCID,VARID,RTEMP),'reading bifurcation_width')
  PTH_WTH=TRANSPOSE(RTEMP)
ELSE
  WRITE(LOGNAM,*) 'Invalid bifurcation_width dimensions: ',LEN1,LEN2,NPTHOUT,NPTHLEV
  STOP 10
ENDIF
DEALLOCATE(RTEMP)

CALL NCERROR(NF90_INQ_VARID(NCID,'bifurcation_manning',VARID),'getting bifurcation_manning id')
CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=DIMIDS1),'reading bifurcation_manning dimensions')
LEV_DIMID=DIMIDS1(1)
CALL NCERROR(NF90_GET_VAR(NCID,VARID,PTH_MAN),'reading bifurcation_manning')
CALL NCERROR(NF90_CLOSE(NCID))

IF( ANY(PTH_UPST<1) .OR. ANY(PTH_UPST>NSEQMAX) .OR. &
    ANY(PTH_DOWN<1) .OR. ANY(PTH_DOWN>NSEQMAX) .OR. &
    ANY(PTH_UPST==PTH_DOWN) )THEN
  WRITE(LOGNAM,*) 'Invalid bifurcation sequence index in routing netCDF'
  STOP 10
ENDIF
IF( ALLOCATED(ROUTING_OLD_TO_NEW) )THEN
  DO IPTH=1,NPTHOUT
    PTH_UPST(IPTH)=ROUTING_OLD_TO_NEW(PTH_UPST(IPTH))
    PTH_DOWN(IPTH)=ROUTING_OLD_TO_NEW(PTH_DOWN(IPTH))
  ENDDO
ENDIF
IF( ANY(.NOT. IEEE_IS_FINITE(PTH_DST)) .OR. ANY(.NOT. IEEE_IS_FINITE(PTH_ELV)) .OR. &
    ANY(.NOT. IEEE_IS_FINITE(PTH_WTH)) .OR. ANY(.NOT. IEEE_IS_FINITE(PTH_MAN)) )THEN
  WRITE(LOGNAM,*) 'Non-finite bifurcation parameter in routing netCDF'
  STOP 10
ENDIF
IF( ANY(PTH_DST<=0._JPRB) .OR. ANY(PTH_WTH<0._JPRB) )THEN
  WRITE(LOGNAM,*) 'Invalid bifurcation distance/width in routing netCDF'
  STOP 10
ENDIF
DO ILEV=1,NPTHLEV
  IF( ANY(PTH_WTH(:,ILEV)>0._JPRB) .AND. PTH_MAN(ILEV)<=0._JPRB )THEN
    WRITE(LOGNAM,*) 'Invalid bifurcation Manning coefficient at level ',ILEV
    STOP 10
  ENDIF
ENDDO

ALLOCATE(OCOUNT(NSEQMAX),ICOUNT(NSEQMAX))
OCOUNT(:)=0
ICOUNT(:)=0
DO IPTH=1,NPTHOUT
  OCOUNT(PTH_UPST(IPTH))=OCOUNT(PTH_UPST(IPTH))+1
  ICOUNT(PTH_DOWN(IPTH))=ICOUNT(PTH_DOWN(IPTH))+1
ENDDO
ONMAX=MAXVAL(OCOUNT)
INMAX=MAXVAL(ICOUNT)
ALLOCATE(I1P_OUT(NSEQMAX,ONMAX),I1P_INF(NSEQMAX,INMAX))
ALLOCATE(I1P_OUTN(NSEQMAX),I1P_INFN(NSEQMAX))
I1P_OUT(:,:)=0
I1P_INF(:,:)=0
I1P_OUTN(:)=0
I1P_INFN(:)=0
DO IPTH=1,NPTHOUT
  ISEQ=PTH_UPST(IPTH)
  JSEQ=PTH_DOWN(IPTH)
  I1P_OUTN(ISEQ)=I1P_OUTN(ISEQ)+1
  I1P_OUT(ISEQ,I1P_OUTN(ISEQ))=IPTH
  I1P_INFN(JSEQ)=I1P_INFN(JSEQ)+1
  I1P_INF(JSEQ,I1P_INFN(JSEQ))=IPTH
ENDDO
DEALLOCATE(OCOUNT,ICOUNT)
END SUBROUTINE READ_ROUTING_BIF_CDF
#endif
SUBROUTINE READ_BIFPARAM    !! evenly allocate pixels to mpi nodes (not used in vcurrent version)
USE YOS_CMF_INPUT,      ONLY: PMANRIV, PMANFLD
USE YOS_CMF_MAP,        ONLY: NPTHOUT, NPTHLEV, PTH_UPST, PTH_DOWN,&
                            & PTH_DST, PTH_ELV, PTH_WTH,  PTH_MAN, NSEQMAX
USE CMF_UTILS_MOD,      ONLY: INQUIRE_FID
IMPLICIT NONE
!* local variables
INTEGER(KIND=JPIM)         :: IX,IY, JX,JY, ISEQ, JSEQ
INTEGER(KIND=JPIM)         :: IPTH,  ILEV,  NPTHOUT1
REAL(KIND=JPRB)            :: PELV,  PWTH,  PDPH
INTEGER(KIND=JPIM)         :: ONMAX,  INMAX
INTEGER(KIND=JPIM)         :: OCOUNT(NSEQMAX),  ICOUNT(NSEQMAX)
!================================================
WRITE(LOGNAM,*)"RIVMAP_INIT: Bifuraction channel:", TRIM(CPTHOUT)

TMPNAM=INQUIRE_FID()
OPEN(TMPNAM,FILE=CPTHOUT,FORM='FORMATTED')
READ(TMPNAM,*) NPTHOUT,NPTHLEV

WRITE(LOGNAM,*) "Bifurcation channel dimantion", NPTHOUT, NPTHLEV

ALLOCATE( PTH_UPST(NPTHOUT) )
ALLOCATE( PTH_DOWN(NPTHOUT) )
ALLOCATE( PTH_DST(NPTHOUT)  )
ALLOCATE( PTH_ELV(NPTHOUT,NPTHLEV) )
ALLOCATE( PTH_WTH(NPTHOUT,NPTHLEV) )
ALLOCATE( PTH_MAN(NPTHLEV)  )

OCOUNT(:)=0
ICOUNT(:)=0

NPTHOUT1=0
DO IPTH=1, NPTHOUT
  READ(TMPNAM,*) IX, IY, JX, JY, PTH_DST(IPTH), PELV, PDPH, (PTH_WTH(IPTH,ILEV),ILEV=1,NPTHLEV)
  PTH_UPST(IPTH)=I2VECTOR(IX,IY)
  PTH_DOWN(IPTH)=I2VECTOR(JX,JY)
  IF (PTH_UPST(IPTH) > 0 .AND. PTH_DOWN(IPTH) > 0) THEN  ! both upst and down grids are within domain
    NPTHOUT1=NPTHOUT1+1
    ISEQ=PTH_UPST(IPTH)
    JSEQ=PTH_DOWN(IPTH)
    OCOUNT(ISEQ)=OCOUNT(ISEQ)+1
    ICOUNT(JSEQ)=ICOUNT(JSEQ)+1
  ENDIF
  DO ILEV=1, NPTHLEV
    IF( ILEV==1 )THEN            !!ILEV=1: water channel bifurcation. consider bifurcation channel depth
      PWTH=PTH_WTH(IPTH,ILEV)
      IF( PWTH>0 )THEN
        PTH_ELV(IPTH,ILEV)=PELV - PDPH
      ELSE
        PTH_ELV(IPTH,ILEV)=1.E20
      ENDIF
    ELSE
      PWTH=PTH_WTH(IPTH,ILEV)
      IF( PWTH>0 )THEN
        PTH_ELV(IPTH,ILEV)=PELV + ILEV - 2.0    !! ILEV=2: bank top level 
      ELSE
        PTH_ELV(IPTH,ILEV)=1.E20
      ENDIF
    ENDIF
  ENDDO
ENDDO
CLOSE(TMPNAM)

DO ILEV=1, NPTHLEV
  IF( ILEV==1 )THEN
    PTH_MAN(ILEV)=PMANRIV
  ELSE
    PTH_MAN(ILEV)=PMANFLD
  ENDIF
ENDDO

IF (NPTHOUT /= NPTHOUT1) THEN
  WRITE(LOGNAM,*)"Bifuraction channel outside of domain. Only valid:", NPTHOUT1
ENDIF

!=====
!!IF( LSPAMAT )THEN
  ONMAX=0
  INMAX=0
  DO ISEQ=1, NSEQMAX
    ONMAX=max(ONMAX,OCOUNT(ISEQ))
    INMAX=max(INMAX,ICOUNT(ISEQ))
  ENDDO
  WRITE(LOGNAM,*) "Max # of Bifuraction channel in each grid (Out, Inf):", ONMAX, INMAX
  
  ALLOCATE(I1P_OUT(NSEQMAX,ONMAX))
  ALLOCATE(I1P_INF(NSEQMAX,INMAX))
  ALLOCATE(I1P_OUTN(NSEQMAX))
  ALLOCATE(I1P_INFN(NSEQMAX))
  I1P_OUT(:,:)=0
  I1P_INF(:,:)=0
  I1P_OUTN(:)=0
  I1P_INFN(:)=0

  DO IPTH=1, NPTHOUT
    IF (PTH_UPST(IPTH) > 0 .AND. PTH_DOWN(IPTH) > 0) THEN  ! both upst and down grids are within domain
      ISEQ=PTH_UPST(IPTH)
      JSEQ=PTH_DOWN(IPTH)
  
      I1P_OUTN(ISEQ)=I1P_OUTN(ISEQ)+1
      I1P_OUT(ISEQ,I1P_OUTN(ISEQ))=IPTH
  
      I1P_INFN(JSEQ)=I1P_INFN(JSEQ)+1
      I1P_INF(JSEQ,I1P_INFN(JSEQ))=IPTH
    ENDIF
  ENDDO
!!ENDIF

END SUBROUTINE READ_BIFPARAM
!==========================================================


END SUBROUTINE CMF_RIVMAP_INIT
