SUBROUTINE CMF_TOPO_INIT
! read & set topography map 
! -- call from CMF_DRV_INIT
USE YOS_CMF_INPUT,  ONLY: TMPNAM,   NX,NY,NLFP, LMAPEND,  &
                        & LFPLAIN,  LMEANSL,  LGDWDLY,  LSLPMIX, LSLOPEMOUTH
USE YOS_CMF_MAP,    ONLY: D2NXTDST, D2GRAREA, D2ELEVTN, D2RIVLEN, &
                        & D2RIVWTH, D2RIVHGT, D2FLDHGT, D2RIVELV, &
                        & D2FLDGRD, D2RIVMAN, D2RIVSTOMAX, D2FLDSTOMAX,  &
                        & DFRCINC,  NSEQMAX,  D2MEANSL, D2DWNELV, &
                        & D2GDWDLY, I2MASK, R2GRDARE, ROUTING_OLD_TO_NEW
IMPLICIT NONE
!================================================
WRITE(LOGNAM,*) ""
WRITE(LOGNAM,*) "!---------------------!"

WRITE(LOGNAM,*) 'CMF::TOPO_INIT: topography map initialization'

! *** 1. ALLOCATE ARRAYS
ALLOCATE( D2GRAREA(NSEQMAX,1) )
ALLOCATE( D2ELEVTN(NSEQMAX,1) )
ALLOCATE( D2NXTDST(NSEQMAX,1) )
ALLOCATE( D2RIVLEN(NSEQMAX,1) )
ALLOCATE( D2RIVWTH(NSEQMAX,1) )
ALLOCATE( D2RIVHGT(NSEQMAX,1) )
ALLOCATE( D2FLDHGT(NSEQMAX,1,NLFP) )
ALLOCATE( D2RIVMAN(NSEQMAX,1) )
ALLOCATE( D2MEANSL(NSEQMAX,1) )
ALLOCATE( D2DWNELV(NSEQMAX,1) )
ALLOCATE( D2GDWDLY(NSEQMAX,1) )
ALLOCATE( I2MASK(NSEQMAX,1)   )
ALLOCATE( R2GRDARE(NX,NY)     )

D2GRAREA(:,:)  =0._JPRB
D2ELEVTN(:,:)  =0._JPRB
D2NXTDST(:,:)  =0._JPRB
D2RIVLEN(:,:)  =0._JPRB
D2RIVWTH(:,:)  =0._JPRB
D2RIVHGT(:,:)  =0._JPRB
D2FLDHGT(:,:,:)=0._JPRB
D2RIVMAN(:,:)  =0._JPRB
D2MEANSL(:,:)  =0._JPRB
D2DWNELV(:,:)  =0._JPRB
D2GDWDLY(:,:)  =0._JPRB
I2MASK(:,:)    =0._JPIM     !! mask for calculation (IFS slopemix: Kinemacti Wave for Mask=1; Reservoir: dam=2, dam upstream=1)
R2GRDARE(:,:)  =0._JPRB

!============================
! *** 2. Read topo map
WRITE(LOGNAM,*) 'CMF::TOPO_INIT: read topography maps'
IF( CROUTINGNC/="NONE" )THEN
  CALL READ_ROUTING_TOPO_CDF
ELSEIF ( .not. LMAPCDF ) THEN
  CALL READ_TOPO_BIN
ELSE
  CALL READ_TOPO_CDF
ENDIF

IF ( CROUTINGNC=="NONE" ) I2MASK(:,:)=0_JPIM
IF ( LSLPMIX .AND. CROUTINGNC=="NONE" ) THEN
  CALL SET_SLOPEMIX
ENDIF

!============================
! *** 3a. Calc Channel Parameters
WRITE(LOGNAM,*) 'TOPO_INIT: calc river channel parameters'

ALLOCATE(D2RIVSTOMAX(NSEQMAX,1))
ALLOCATE(D2RIVELV(NSEQMAX,1))

IF ( LFPLAIN ) THEN
  D2RIVSTOMAX(:,:) = D2RIVLEN(:,:) * D2RIVWTH(:,:) * D2RIVHGT(:,:)
ELSE
  WRITE(LOGNAM,*) 'TOPO_INIT: no floodplain (rivstomax=1.D18)'
  D2RIVSTOMAX(:,:) = 1.E18
ENDIF
D2RIVELV(:,:) = D2ELEVTN(:,:) - D2RIVHGT(:,:)

!*** 3b. Calc Channel Parameters
WRITE(LOGNAM,*) 'TOPO_INIT: calc floodplain parameters'

ALLOCATE(D2FLDSTOMAX(NSEQMAX,1,NLFP))
ALLOCATE(D2FLDGRD(NSEQMAX,1,NLFP))
CALL SET_FLDSTG

!*** 3c. Calc downstream boundary
WRITE(LOGNAM,*) 'TOPO_INIT: calc downstream boundary elevation'
D2DWNELV(:,:)=D2ELEVTN(:,:)
IF( LMEANSL ) THEN
  D2DWNELV(:,:)=D2ELEVTN(:,:)+D2MEANSL(:,:)
ENDIF

CONTAINS
!==========================================================
!+ READ_TOPO_BIN
!+ READ_TOPO_CDF
!+ SET_FLDSTG
!+ SET_SLOPEMIX
!==========================================================
#ifdef UseCDF_CMF
SUBROUTINE READ_ROUTING_TOPO_CDF
USE, INTRINSIC :: IEEE_ARITHMETIC, ONLY: IEEE_IS_FINITE
USE YOS_CMF_INPUT, ONLY: WEST,EAST,NORTH,SOUTH
USE YOS_CMF_MAP, ONLY: D2ELEVSLOPE
USE CMF_UTILS_MOD, ONLY: NCERROR
USE NETCDF
IMPLICIT NONE
INTEGER(KIND=JPIM) :: NCID,VARID,STATUS,ILEV,IY,DIMIDS2(2),LEN1,LEN2,ISEQ,SEQDIM(1)
INTEGER(KIND=JPIM),ALLOCATABLE :: ITMP(:)
REAL(KIND=JPRB),ALLOCATABLE :: RTEMP(:,:),RIVELV(:),STO_IN(:),STO_EXPECT(:),R1(:),R3(:,:)
REAL(KIND=JPRB) :: DLON,DLAT,LATN,LATS,ROWEAREA
LOGICAL :: HAVE_PERM
REAL(KIND=JPRB),PARAMETER :: REARTH=6371220._JPRB
REAL(KIND=JPRB),PARAMETER :: DEG2RAD=1.7453292519943296E-2_JPRB

CALL NCERROR(NF90_OPEN(TRIM(CROUTINGNC),NF90_NOWRITE,NCID), &
             'opening '//TRIM(CROUTINGNC))
CALL NCERROR(NF90_INQ_VARID(NCID,'seq_x',VARID),'getting seq_x id')
CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=SEQDIM),'reading sequence dimension')
CALL NCERROR(NF90_INQ_VARID(NCID,'topo_area',VARID),'getting topo_area id')
CALL NCERROR(NF90_GET_VAR(NCID,VARID,D2GRAREA(:,1)),'reading topo_area')

STATUS=NF90_INQ_VARID(NCID,'topo_distance',VARID)
IF( STATUS/=NF90_NOERR ) STATUS=NF90_INQ_VARID(NCID,'topo_nxtdst',VARID)
IF( STATUS/=NF90_NOERR )THEN
  WRITE(LOGNAM,*) 'topo_distance/topo_nxtdst not present in routing netCDF'
  WRITE(LOGNAM,*) 'Cannot derive downstream distance from topo_rivlen safely.'
  STOP 10
ENDIF
CALL NCERROR(NF90_GET_VAR(NCID,VARID,D2NXTDST(:,1)),'reading topo_distance')

CALL NCERROR(NF90_INQ_VARID(NCID,'topo_rivlen',VARID),'getting topo_rivlen id')
CALL NCERROR(NF90_GET_VAR(NCID,VARID,D2RIVLEN(:,1)),'reading topo_rivlen')
CALL NCERROR(NF90_INQ_VARID(NCID,'topo_rivwth',VARID),'getting topo_rivwth id')
CALL NCERROR(NF90_GET_VAR(NCID,VARID,D2RIVWTH(:,1)),'reading topo_rivwth')
CALL NCERROR(NF90_INQ_VARID(NCID,'topo_rivhgt',VARID),'getting topo_rivhgt id')
CALL NCERROR(NF90_GET_VAR(NCID,VARID,D2RIVHGT(:,1)),'reading topo_rivhgt')
CALL NCERROR(NF90_INQ_VARID(NCID,'topo_rivman',VARID),'getting topo_rivman id')
CALL NCERROR(NF90_GET_VAR(NCID,VARID,D2RIVMAN(:,1)),'reading topo_rivman')

STATUS=NF90_INQ_VARID(NCID,'topo_rivelv',VARID)
IF( STATUS==NF90_NOERR )THEN
  ALLOCATE(RIVELV(NSEQMAX))
  CALL NCERROR(NF90_GET_VAR(NCID,VARID,RIVELV),'reading topo_rivelv')
  D2ELEVTN(:,1)=RIVELV(:)+D2RIVHGT(:,1)
  DEALLOCATE(RIVELV)
ELSE
  STATUS=NF90_INQ_VARID(NCID,'topo_elevation',VARID)
  IF( STATUS/=NF90_NOERR )THEN
    WRITE(LOGNAM,*) 'topo_elevation/topo_rivelv not present in routing netCDF'
    WRITE(LOGNAM,*) 'Need bank elevation or river-bed elevation plus topo_rivhgt.'
    STOP 10
  ENDIF
  CALL NCERROR(NF90_GET_VAR(NCID,VARID,D2ELEVTN(:,1)),'reading topo_elevation')
ENDIF

CALL NCERROR(NF90_INQ_VARID(NCID,'topo_fldhgt',VARID),'getting topo_fldhgt id')
CALL NCERROR(NF90_INQUIRE_VARIABLE(NCID,VARID,DIMIDS=DIMIDS2),'reading topo_fldhgt dimensions')
CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS2(1),LEN=LEN1),'reading topo_fldhgt dimension')
CALL NCERROR(NF90_INQUIRE_DIMENSION(NCID,DIMIDS2(2),LEN=LEN2),'reading topo_fldhgt dimension')
IF( DIMIDS2(1)==SEQDIM(1) .AND. LEN1==NSEQMAX .AND. LEN2==NLFP )THEN
  ALLOCATE(RTEMP(NSEQMAX,NLFP))
  CALL NCERROR(NF90_GET_VAR(NCID,VARID,RTEMP),'reading topo_fldhgt')
  DO ILEV=1,NLFP
    D2FLDHGT(:,1,ILEV)=RTEMP(:,ILEV)
  ENDDO
  DEALLOCATE(RTEMP)
ELSEIF( DIMIDS2(2)==SEQDIM(1) .AND. LEN1==NLFP .AND. LEN2==NSEQMAX )THEN
  ALLOCATE(RTEMP(NLFP,NSEQMAX))
  CALL NCERROR(NF90_GET_VAR(NCID,VARID,RTEMP),'reading topo_fldhgt')
  DO ILEV=1,NLFP
    D2FLDHGT(:,1,ILEV)=RTEMP(ILEV,:)
  ENDDO
  DEALLOCATE(RTEMP)
ELSE
  WRITE(LOGNAM,*) 'topo_fldhgt dimensions do not match sequence count and NLFP: ',LEN1,LEN2,NSEQMAX,NLFP
  STOP 10
ENDIF

IF( LSLOPEMOUTH )THEN
  ALLOCATE(D2ELEVSLOPE(NSEQMAX,1))
  STATUS=NF90_INQ_VARID(NCID,'topo_elevslope',VARID)
  IF( STATUS/=NF90_NOERR ) STATUS=NF90_INQ_VARID(NCID,'elevslope',VARID)
  IF( STATUS/=NF90_NOERR )THEN
    WRITE(LOGNAM,*) 'topo_elevslope not present in routing netCDF'
    STOP 10
  ENDIF
  CALL NCERROR(NF90_GET_VAR(NCID,VARID,D2ELEVSLOPE(:,1)),'reading topo_elevslope')
  IF( ANY(.NOT. IEEE_IS_FINITE(D2ELEVSLOPE(:,1))) .OR. ANY(D2ELEVSLOPE(:,1)<=0._JPRB) )THEN
    WRITE(LOGNAM,*) 'Invalid topo_elevslope in routing netCDF'
    STOP 10
  ENDIF
ENDIF
IF( LSLPMIX )THEN
  STATUS=NF90_INQ_VARID(NCID,'topo_mask_slope',VARID)
  IF( STATUS/=NF90_NOERR ) STATUS=NF90_INQ_VARID(NCID,'mask_slope',VARID)
  IF( STATUS/=NF90_NOERR )THEN
    WRITE(LOGNAM,*) 'topo_mask_slope not present in routing netCDF'
    STOP 10
  ENDIF
  CALL NCERROR(NF90_GET_VAR(NCID,VARID,I2MASK(:,1)),'reading topo_mask_slope')
  IF( ANY(I2MASK(:,1)<0) .OR. ANY(I2MASK(:,1)>1) )THEN
    WRITE(LOGNAM,*) 'Invalid topo_mask_slope in routing netCDF'
    STOP 10
  ENDIF
ENDIF
IF( LGDWDLY )THEN
  STATUS=NF90_INQ_VARID(NCID,'topo_gdwdly',VARID)
  IF( STATUS/=NF90_NOERR ) STATUS=NF90_INQ_VARID(NCID,'gdwdly',VARID)
  IF( STATUS/=NF90_NOERR )THEN
    WRITE(LOGNAM,*) 'topo_gdwdly not present in routing netCDF'
    STOP 10
  ENDIF
  CALL NCERROR(NF90_GET_VAR(NCID,VARID,D2GDWDLY(:,1)),'reading topo_gdwdly')
  IF( ANY(.NOT. IEEE_IS_FINITE(D2GDWDLY(:,1))) .OR. ANY(D2GDWDLY(:,1)<0._JPRB) )THEN
    WRITE(LOGNAM,*) 'Invalid topo_gdwdly in routing netCDF'
    STOP 10
  ENDIF
ENDIF
IF( LMEANSL )THEN
  STATUS=NF90_INQ_VARID(NCID,'topo_meansl',VARID)
  IF( STATUS/=NF90_NOERR ) STATUS=NF90_INQ_VARID(NCID,'meansl',VARID)
  IF( STATUS/=NF90_NOERR )THEN
    WRITE(LOGNAM,*) 'topo_meansl not present in routing netCDF'
    STOP 10
  ENDIF
  CALL NCERROR(NF90_GET_VAR(NCID,VARID,D2MEANSL(:,1)),'reading topo_meansl')
  IF( ANY(.NOT. IEEE_IS_FINITE(D2MEANSL(:,1))) )THEN
    WRITE(LOGNAM,*) 'Invalid topo_meansl in routing netCDF'
    STOP 10
  ENDIF
ENDIF

HAVE_PERM=ALLOCATED(ROUTING_OLD_TO_NEW)
IF( HAVE_PERM )THEN
  ALLOCATE(R1(NSEQMAX),R3(NSEQMAX,NLFP))
  R1(:)=D2GRAREA(:,1); DO ISEQ=1,NSEQMAX; D2GRAREA(ROUTING_OLD_TO_NEW(ISEQ),1)=R1(ISEQ); ENDDO
  R1(:)=D2ELEVTN(:,1); DO ISEQ=1,NSEQMAX; D2ELEVTN(ROUTING_OLD_TO_NEW(ISEQ),1)=R1(ISEQ); ENDDO
  R1(:)=D2NXTDST(:,1); DO ISEQ=1,NSEQMAX; D2NXTDST(ROUTING_OLD_TO_NEW(ISEQ),1)=R1(ISEQ); ENDDO
  R1(:)=D2RIVLEN(:,1); DO ISEQ=1,NSEQMAX; D2RIVLEN(ROUTING_OLD_TO_NEW(ISEQ),1)=R1(ISEQ); ENDDO
  R1(:)=D2RIVWTH(:,1); DO ISEQ=1,NSEQMAX; D2RIVWTH(ROUTING_OLD_TO_NEW(ISEQ),1)=R1(ISEQ); ENDDO
  R1(:)=D2RIVHGT(:,1); DO ISEQ=1,NSEQMAX; D2RIVHGT(ROUTING_OLD_TO_NEW(ISEQ),1)=R1(ISEQ); ENDDO
  R1(:)=D2RIVMAN(:,1); DO ISEQ=1,NSEQMAX; D2RIVMAN(ROUTING_OLD_TO_NEW(ISEQ),1)=R1(ISEQ); ENDDO
  DO ILEV=1,NLFP
    R3(:,ILEV)=D2FLDHGT(:,1,ILEV)
  ENDDO
  DO ISEQ=1,NSEQMAX
    DO ILEV=1,NLFP
      D2FLDHGT(ROUTING_OLD_TO_NEW(ISEQ),1,ILEV)=R3(ISEQ,ILEV)
    ENDDO
  ENDDO
  IF( LMEANSL )THEN
    R1(:)=D2MEANSL(:,1); DO ISEQ=1,NSEQMAX; D2MEANSL(ROUTING_OLD_TO_NEW(ISEQ),1)=R1(ISEQ); ENDDO
  ENDIF
  IF( LGDWDLY )THEN
    R1(:)=D2GDWDLY(:,1); DO ISEQ=1,NSEQMAX; D2GDWDLY(ROUTING_OLD_TO_NEW(ISEQ),1)=R1(ISEQ); ENDDO
  ENDIF
  IF( LSLOPEMOUTH )THEN
    R1(:)=D2ELEVSLOPE(:,1); DO ISEQ=1,NSEQMAX; D2ELEVSLOPE(ROUTING_OLD_TO_NEW(ISEQ),1)=R1(ISEQ); ENDDO
  ENDIF
  IF( LSLPMIX )THEN
    ALLOCATE(ITMP(NSEQMAX))
    ITMP(:)=I2MASK(:,1)
    DO ISEQ=1,NSEQMAX
      I2MASK(ROUTING_OLD_TO_NEW(ISEQ),1)=ITMP(ISEQ)
    ENDDO
    DEALLOCATE(ITMP)
  ENDIF
  DEALLOCATE(R1,R3)
ENDIF

IF( ANY(.NOT. IEEE_IS_FINITE(D2GRAREA(:,1))) .OR. ANY(.NOT. IEEE_IS_FINITE(D2ELEVTN(:,1))) .OR. &
    ANY(.NOT. IEEE_IS_FINITE(D2NXTDST(:,1))) .OR. ANY(.NOT. IEEE_IS_FINITE(D2RIVLEN(:,1))) .OR. &
    ANY(.NOT. IEEE_IS_FINITE(D2RIVWTH(:,1))) .OR. ANY(.NOT. IEEE_IS_FINITE(D2RIVHGT(:,1))) .OR. &
    ANY(.NOT. IEEE_IS_FINITE(D2RIVMAN(:,1))) .OR. ANY(.NOT. IEEE_IS_FINITE(D2FLDHGT(:,1,:))) )THEN
  WRITE(LOGNAM,*) 'Non-finite routing topography parameter in ',TRIM(CROUTINGNC)
  STOP 10
ENDIF
IF( ANY(D2GRAREA(:,1)<=0._JPRB) .OR. ANY(D2NXTDST(:,1)<=0._JPRB) .OR. &
    ANY(D2RIVLEN(:,1)<=0._JPRB) .OR. ANY(D2RIVWTH(:,1)<=0._JPRB) .OR. &
    ANY(D2RIVHGT(:,1)<=0._JPRB) .OR. ANY(D2RIVMAN(:,1)<=0._JPRB) )THEN
  WRITE(LOGNAM,*) 'Non-positive routing topography parameter in ',TRIM(CROUTINGNC)
  STOP 10
ENDIF
IF( ANY(D2FLDHGT(:,1,1)<0._JPRB) )THEN
  WRITE(LOGNAM,*) 'Negative floodplain height in routing netCDF'
  STOP 10
ENDIF
DO ILEV=2,NLFP
  IF( ANY(D2FLDHGT(:,1,ILEV)<D2FLDHGT(:,1,ILEV-1)) )THEN
    WRITE(LOGNAM,*) 'Floodplain height profile is not monotonic at level ',ILEV
    STOP 10
  ENDIF
ENDDO

STATUS=NF90_INQ_VARID(NCID,'topo_rivstomax',VARID)
IF( STATUS==NF90_NOERR )THEN
  ALLOCATE(STO_IN(NSEQMAX),STO_EXPECT(NSEQMAX))
  CALL NCERROR(NF90_GET_VAR(NCID,VARID,STO_IN),'reading topo_rivstomax')
  IF( HAVE_PERM )THEN
    ALLOCATE(R1(NSEQMAX))
    R1(:)=STO_IN(:)
    DO ISEQ=1,NSEQMAX
      STO_IN(ROUTING_OLD_TO_NEW(ISEQ))=R1(ISEQ)
    ENDDO
    DEALLOCATE(R1)
  ENDIF
  STO_EXPECT(:)=D2RIVLEN(:,1)*D2RIVWTH(:,1)*D2RIVHGT(:,1)
  IF( ANY(.NOT. IEEE_IS_FINITE(STO_IN)) .OR. &
      ANY(ABS(STO_IN-STO_EXPECT)>MAX(1.0E-6_JPRB,ABS(STO_EXPECT)*1.0E-6_JPRB)) )THEN
    WRITE(LOGNAM,*) 'topo_rivstomax is inconsistent with CaMa river geometry'
    STOP 10
  ENDIF
  DEALLOCATE(STO_IN,STO_EXPECT)
ENDIF

CALL NCERROR(NF90_CLOSE(NCID))

DLON=(EAST-WEST)/REAL(NX,KIND=JPRB)*DEG2RAD
DLAT=(NORTH-SOUTH)/REAL(NY,KIND=JPRB)
DO IY=1,NY
  LATN=(NORTH-REAL(IY-1,KIND=JPRB)*DLAT)*DEG2RAD
  LATS=(NORTH-REAL(IY,  KIND=JPRB)*DLAT)*DEG2RAD
  ROWEAREA=REARTH*REARTH*DLON*(SIN(LATN)-SIN(LATS))
  R2GRDARE(:,IY)=ROWEAREA
ENDDO
END SUBROUTINE READ_ROUTING_TOPO_CDF
#else
SUBROUTINE READ_ROUTING_TOPO_CDF
IMPLICIT NONE
WRITE(LOGNAM,*) 'CROUTINGNC requires compiling CaMa with UseCDF_CMF'
STOP 10
END SUBROUTINE READ_ROUTING_TOPO_CDF
#endif
SUBROUTINE READ_TOPO_BIN
USE CMF_UTILS_MOD,       ONLY: mapR2vecD, CONV_END,  INQUIRE_FID
IMPLICIT NONE
!* local variables
INTEGER(KIND=JPIM)          :: ILFP
REAL(KIND=JPRM),ALLOCATABLE :: R2TEMP(:,:)
REAL(KIND=JPRB),ALLOCATABLE :: D2TEMP(:,:)
!================================================
ALLOCATE(R2TEMP(NX,NY))
ALLOCATE(D2TEMP(NSEQMAX,1))

TMPNAM=INQUIRE_FID()

WRITE(LOGNAM,*)'TOPO_INIT: unit-catchment area : ',TRIM(CGRAREA) 
OPEN(TMPNAM,FILE=CGRAREA,FORM='UNFORMATTED',ACCESS='DIRECT',RECL=4*NX*NY)
READ(TMPNAM,REC=1) R2TEMP(:,:)
  IF( LMAPEND ) CALL CONV_END(R2TEMP,NX,NY)
CALL mapR2vecD(R2TEMP,D2GRAREA)
CLOSE(TMPNAM)

WRITE(LOGNAM,*)'TOPO_INIT: ground elevation : ',TRIM(CELEVTN)
OPEN(TMPNAM,FILE=CELEVTN,FORM='UNFORMATTED',ACCESS='DIRECT',RECL=4*NX*NY)
READ(TMPNAM,REC=1) R2TEMP(:,:)
  IF( LMAPEND ) CALL CONV_END(R2TEMP,NX,NY)
CALL mapR2vecD(R2TEMP,D2ELEVTN)
CLOSE(TMPNAM)

WRITE(LOGNAM,*)'TOPO_INIT: downstream distance : ',TRIM(CNXTDST)
OPEN(TMPNAM,FILE=CNXTDST,FORM='UNFORMATTED',ACCESS='DIRECT',RECL=4*NX*NY)
READ(TMPNAM,REC=1) R2TEMP(:,:)
  IF( LMAPEND ) CALL CONV_END(R2TEMP,NX,NY)
CALL mapR2vecD(R2TEMP,D2NXTDST)
CLOSE(TMPNAM)

WRITE(LOGNAM,*)'TOPO_INIT: river channel length : ',TRIM(CRIVLEN)
OPEN(TMPNAM,FILE=CRIVLEN,FORM='UNFORMATTED',ACCESS='DIRECT',RECL=4*NX*NY)
READ(TMPNAM,REC=1) R2TEMP(:,:)
  IF( LMAPEND ) CALL CONV_END(R2TEMP,NX,NY)
CALL mapR2vecD(R2TEMP,D2RIVLEN)
CLOSE(TMPNAM)

WRITE(LOGNAM,*)'TOPO_INIT: floodplain elevation profile : ',TRIM(CFLDHGT)
OPEN(TMPNAM,FILE=TRIM(CFLDHGT),FORM='UNFORMATTED',ACCESS='DIRECT',RECL=4*NX*NY)
DO ILFP=1,NLFP
  READ(TMPNAM,REC=ILFP) R2TEMP
  IF( LMAPEND ) CALL CONV_END(R2TEMP,NX,NY)
  CALL mapR2vecD(R2TEMP,D2TEMP)
  D2FLDHGT(:,:,ILFP)= D2TEMP(:,:)
ENDDO
CLOSE(TMPNAM)

WRITE(LOGNAM,*)'TOPO_INIT: grid area : ',TRIM(CGRDARE)
OPEN(TMPNAM,FILE=TRIM(CGRDARE),FORM='UNFORMATTED',ACCESS='DIRECT',RECL=4*NX*NY)
READ(TMPNAM,REC=1) R2TEMP(:,:)
  IF( LMAPEND ) CALL CONV_END(R2TEMP,NX,NY)
R2GRDARE(:,:) = R2TEMP(:,:)
CLOSE(TMPNAM)

!*** river channel / groundwater parameters)

WRITE(LOGNAM,*)'TOPO_INIT: river channel depth : ',TRIM(CRIVHGT)
OPEN(TMPNAM,FILE=CRIVHGT,FORM='UNFORMATTED',ACCESS='DIRECT',RECL=4*NX*NY)
READ(TMPNAM,REC=1) R2TEMP(:,:)
  IF( LMAPEND ) CALL CONV_END(R2TEMP,NX,NY)
CALL mapR2vecD(R2TEMP,D2RIVHGT)
CLOSE(TMPNAM)

WRITE(LOGNAM,*)'TOPO_INIT: river channel width : ',TRIM(CRIVWTH)
OPEN(TMPNAM,FILE=CRIVWTH,FORM='UNFORMATTED',ACCESS='DIRECT',RECL=4*NX*NY)
READ(TMPNAM,REC=1) R2TEMP(:,:)
  IF( LMAPEND ) CALL CONV_END(R2TEMP,NX,NY)
CALL mapR2vecD(R2TEMP,D2RIVWTH)
CLOSE(TMPNAM)

WRITE(LOGNAM,*)'TOPO_INIT: manning coefficient river: ',TRIM(CRIVMAN)
OPEN(TMPNAM,FILE=TRIM(CRIVMAN),FORM='UNFORMATTED',ACCESS='DIRECT',RECL=4*NX*NY)
READ(TMPNAM,REC=1) R2TEMP(:,:)
  IF( LMAPEND ) CALL CONV_END(R2TEMP,NX,NY)
CALL mapR2vecD(R2TEMP,D2RIVMAN)
CLOSE(TMPNAM)

IF( LGDWDLY )THEN
  WRITE(LOGNAM,*)'TOPO_INIT: groundwater delay parameter: ',TRIM(CGDWDLY)
  OPEN(TMPNAM,FILE=TRIM(CGDWDLY),FORM='UNFORMATTED',ACCESS='DIRECT',RECL=4*NX*NY)
  READ(TMPNAM,REC=1) R2TEMP(:,:)
    IF( LMAPEND ) CALL CONV_END(R2TEMP,NX,NY)
  CALL mapR2vecD(R2TEMP,D2GDWDLY)
  CLOSE(TMPNAM)
ENDIF

IF( LSLPMIX )THEN
  WRITE(LOGNAM,*)'TOPO_INIT: LSLPMIX only used in IFS, not availabke with binary map'
ENDIF
IF( LSLOPEMOUTH )THEN
  WRITE(LOGNAM,*)'TOPO_INIT: LSLOPEMOUTH only used in IFS, not availabke with binary map'
ENDIF

! ==========

IF( LMEANSL ) THEN
  WRITE(LOGNAM, *)'TOPO_INIT: mean sea level: ', TRIM(CMEANSL)
  OPEN(TMPNAM, FILE=CMEANSL, FORM='UNFORMATTED', ACCESS='DIRECT', RECL=4*NX*NY)
  READ(TMPNAM, REC=1) R2TEMP(:,:)
    IF( LMAPEND ) CALL CONV_END(R2TEMP,NX,NY)
  CALL mapR2vecD(R2TEMP, D2MEANSL)
  CLOSE(TMPNAM)
ENDIF

DEALLOCATE(R2TEMP)
DEALLOCATE(D2TEMP)

END SUBROUTINE READ_TOPO_BIN
!==========================================================
!+
!+
!+
!==========================================================
SUBROUTINE READ_TOPO_CDF
#ifdef UseCDF_CMF
USE NETCDF 
USE CMF_UTILS_MOD,            ONLY: NCERROR,mapR2vecD
USE YOS_CMF_MAP,              ONLY: D2ELEVSLOPE     !! only used in ECMWF
IMPLICIT NONE
!* local variables
INTEGER(KIND=JPIM)               :: NCID,VARID,STATUS
INTEGER(KIND=JPIM)               :: ILEV
REAL(KIND=JPRM),ALLOCATABLE      :: R2TEMP(:,:)
REAL(KIND=JPRB),ALLOCATABLE      :: D2TEMP(:,:)
!================================================
ALLOCATE(R2TEMP(NX,NY))
ALLOCATE(D2TEMP(NSEQMAX,1))

!! CLIM FILE
CALL NCERROR (NF90_OPEN(CRIVCLINC,NF90_NOWRITE,NCID),'opening '//TRIM(CRIVCLINC) )

WRITE(LOGNAM,*)'TOPO_INIT: ctmare:',TRIM(CRIVCLINC)
CALL NCERROR ( NF90_INQ_VARID(NCID,'ctmare',VARID),'getting id' )
CALL NCERROR ( NF90_GET_VAR(NCID,VARID,R2TEMP),'reading data' )
CALL mapR2vecD(R2TEMP,D2GRAREA)

WRITE(LOGNAM,*)'TOPO_INIT: elevtn:',TRIM(CRIVCLINC)
CALL NCERROR ( NF90_INQ_VARID(NCID,'elevtn',VARID),'getting id' )
CALL NCERROR ( NF90_GET_VAR(NCID,VARID,R2TEMP),'reading data' ) 
CALL mapR2vecD(R2TEMP,D2ELEVTN)

WRITE(LOGNAM,*)'TOPO_INIT: nxtdst:',TRIM(CRIVCLINC)
CALL NCERROR ( NF90_INQ_VARID(NCID,'nxtdst',VARID),'getting id' )
CALL NCERROR ( NF90_GET_VAR(NCID,VARID,R2TEMP),'reading data' ) 
CALL mapR2vecD(R2TEMP,D2NXTDST)

WRITE(LOGNAM,*)'TOPO_INIT: rivlen:',TRIM(CRIVCLINC)
CALL NCERROR ( NF90_INQ_VARID(NCID,'rivlen',VARID),'getting id' )
CALL NCERROR ( NF90_GET_VAR(NCID,VARID,R2TEMP),'reading data' ) 
CALL mapR2vecD(R2TEMP,D2RIVLEN)

WRITE(LOGNAM,*)'TOPO_INIT: fldhgt:',TRIM(CRIVCLINC)
CALL NCERROR ( NF90_INQ_VARID(NCID,'fldhgt',VARID),'getting id' )
DO ILEV=1,NLFP
  CALL NCERROR ( NF90_GET_VAR(NCID,VARID,R2TEMP,(/1,1,ILEV/),(/NX,NY,1/)),'reading data' ) 
  CALL mapR2vecD(R2TEMP,D2TEMP)
  D2FLDHGT(:,:,ILEV)=D2TEMP(:,:)
ENDDO

CALL NCERROR( NF90_CLOSE(NCID))

IF ( LSLOPEMOUTH ) THEN
  ALLOCATE( D2ELEVSLOPE(NSEQMAX,1) )
  WRITE(LOGNAM,*)'TOPO_INIT: elevslope:',TRIM(CRIVPARNC)
  STATUS = NF90_INQ_VARID(NCID,'elevslope',VARID)
  IF (STATUS /= 0 ) THEN
    WRITE(LOGNAM,*)'TOPO_INIT: elevslope: not present, aborting'
    STOP 9 
  ELSE
    CALL NCERROR ( NF90_GET_VAR(NCID,VARID,R2TEMP),'reading data' ) 
  ENDIF 
  CALL mapR2vecD(R2TEMP,D2ELEVSLOPE)
ENDIF

!!========== 
!! PAR FILE (river channel / groundwater parameters)
CALL NCERROR (NF90_OPEN(CRIVPARNC,NF90_NOWRITE,NCID),'opening '//TRIM(CRIVPARNC) )

WRITE(LOGNAM,*)'TOPO_INIT: rivwth:',TRIM(CRIVPARNC)
CALL NCERROR ( NF90_INQ_VARID(NCID,'rivwth',VARID),'getting id' )
CALL NCERROR ( NF90_GET_VAR(NCID,VARID,R2TEMP),'reading data' ) 
CALL mapR2vecD(R2TEMP,D2RIVWTH)

WRITE(LOGNAM,*)'TOPO_INIT: rivhgt:',TRIM(CRIVPARNC)
CALL NCERROR ( NF90_INQ_VARID(NCID,'rivhgt',VARID),'getting id' )
CALL NCERROR ( NF90_GET_VAR(NCID,VARID,R2TEMP),'reading data' ) 
CALL mapR2vecD(R2TEMP,D2RIVHGT)

WRITE(LOGNAM,*)'TOPO_INIT: rivman:',TRIM(CRIVPARNC)
CALL NCERROR ( NF90_INQ_VARID(NCID,'rivman',VARID),'getting id' )
CALL NCERROR ( NF90_GET_VAR(NCID,VARID,R2TEMP),'reading data' ) 
CALL mapR2vecD(R2TEMP,D2RIVMAN)

IF ( LGDWDLY ) THEN
  WRITE(LOGNAM,*)'TOPO_INIT: GDWDLY:',TRIM(CRIVPARNC)
  STATUS = NF90_INQ_VARID(NCID,'gdwdly',VARID)
  IF (STATUS /= 0 ) THEN
    WRITE(LOGNAM,*)'TOPO_INIT: GDWDLY: not present, setting to zero'
    R2TEMP(:,:) = 0._JPRB
  ELSE
    CALL NCERROR ( NF90_GET_VAR(NCID,VARID,R2TEMP),'reading data' ) 
  ENDIF 
  CALL mapR2vecD(R2TEMP,D2GDWDLY)
ENDIF

CALL NCERROR( NF90_CLOSE(NCID))

!!========== 
!! MEAN SEA LEVEL FILE
IF( LMEANSL ) THEN
  CALL NCERROR (NF90_OPEN(CMEANSLNC,NF90_NOWRITE,NCID),'opening '//TRIM(CMEANSLNC) )
  WRITE(LOGNAM,*)'TOPO_INIT: rivhgt:',TRIM(CMEANSLNC)
  CALL NCERROR ( NF90_INQ_VARID(NCID,'meansl',VARID),'getting id' )
  CALL NCERROR ( NF90_GET_VAR(NCID,VARID,R2TEMP),'reading data' ) 
  CALL mapR2vecD ( R2TEMP,D2MEANSL  )
  CALL NCERROR ( NF90_CLOSE(NCID) )
ENDIF 

DEALLOCATE(R2TEMP)
DEALLOCATE(D2TEMP)
#endif
END SUBROUTINE READ_TOPO_CDF
!==========================================================
!+
!+
!+
!==========================================================
SUBROUTINE SET_FLDSTG
IMPLICIT NONE
!* local variables
INTEGER(KIND=JPIM),SAVE  ::  ISEQ, I
REAL(KIND=JPRB),SAVE     ::  DSTONOW
REAL(KIND=JPRB),SAVE     ::  DSTOPRE
REAL(KIND=JPRB),SAVE     ::  DHGTPRE
REAL(KIND=JPRB),SAVE     ::  DWTHINC
!$OMP THREADPRIVATE               (I,DSTONOW,DSTOPRE,DHGTPRE,DWTHINC)
!================================================
D2FLDSTOMAX(:,:,:) = 0._JPRD
D2FLDGRD(:,:,:)    = 0._JPRB
DFRCINC=REAL(NLFP,KIND=JPRB)**(-1.)
!
!$OMP PARALLEL DO
DO ISEQ=1, NSEQMAX
  DSTOPRE = D2RIVSTOMAX(ISEQ,1)
  DHGTPRE = 0._JPRB
  DWTHINC = D2GRAREA(ISEQ,1) * D2RIVLEN(ISEQ,1)**(-1.) * DFRCINC
  DO I=1, NLFP
    DSTONOW = D2RIVLEN(ISEQ,1) * ( D2RIVWTH(ISEQ,1) + DWTHINC*(REAL(I,KIND=JPRB)-0.5) ) * (D2FLDHGT(ISEQ,1,I)-DHGTPRE)
    D2FLDSTOMAX(ISEQ,1,I) = DSTOPRE + DSTONOW
    D2FLDGRD(ISEQ,1,I) = (D2FLDHGT(ISEQ,1,I)-DHGTPRE) * DWTHINC**(-1.)
    DSTOPRE = D2FLDSTOMAX(ISEQ,1,I)
    DHGTPRE = D2FLDHGT(ISEQ,1,I)
  ENDDO
ENDDO
!$OMP END PARALLEL DO

!
END SUBROUTINE SET_FLDSTG
